// GraphServiceHandler is an implementation of the goap.graph.v1.GraphService service.
type GraphServiceHandler interface {
	// Domain axis
	GetNode(context.Context, *connect.Request[v1.GetNodeRequest]) (*connect.Response[v1.GetNodeResponse], error)
	ListBaselines(context.Context, *connect.Request[v1.ListBaselinesRequest]) (*connect.Response[v1.ListBaselinesResponse], error)
	// Tags (ADR 0056) name the state an applied change leaves; not unique, a name may label several changes.
	TagChange(context.Context, *connect.Request[v1.TagChangeRequest]) (*connect.Response[v1.TagChangeResponse], error)
	ListTags(context.Context, *connect.Request[v1.ListTagsRequest]) (*connect.Response[v1.ListTagsResponse], error)
	DeleteTag(context.Context, *connect.Request[v1.DeleteTagRequest]) (*connect.Response[v1.DeleteTagResponse], error)
	GetBaselineGraph(context.Context, *connect.Request[v1.GetBaselineGraphRequest]) (*connect.Response[v1.GetBaselineGraphResponse], error)
	// Browsing a large baseline: a page of its nodes (by type, filtered) and the neighbourhood of one node.
	ListBaselineNodes(context.Context, *connect.Request[v1.ListBaselineNodesRequest]) (*connect.Response[v1.ListBaselineNodesResponse], error)
	ListBaselineLinks(context.Context, *connect.Request[v1.ListBaselineLinksRequest]) (*connect.Response[v1.ListBaselineLinksResponse], error)
	GetNodeNeighbourhood(context.Context, *connect.Request[v1.GetNodeNeighbourhoodRequest]) (*connect.Response[v1.GetNodeNeighbourhoodResponse], error)
	// The namespaces holding at least one node.
	ListNamespaces(context.Context, *connect.Request[v1.ListNamespacesRequest]) (*connect.Response[v1.ListNamespacesResponse], error)
	// The structures of the graph (ADR 0054): the organisation and the projects, with the node types belonging to each.
	GetStructures(context.Context, *connect.Request[v1.GetStructuresRequest]) (*connect.Response[v1.GetStructuresResponse], error)
	// Whether a node type is written by platform administrators only (`adminOnly:` on the node type, ADR 0068).
	IsAdminOnlyType(context.Context, *connect.Request[v1.IsAdminOnlyTypeRequest]) (*connect.Response[v1.IsAdminOnlyTypeResponse], error)
	ListNodeChanges(context.Context, *connect.Request[v1.ListNodeChangesRequest]) (*connect.Response[v1.ListNodeChangesResponse], error)
	// Version branches (ADR 0009)
	CreateBranch(context.Context, *connect.Request[v1.CreateBranchRequest]) (*connect.Response[v1.CreateBranchResponse], error)
	ListBranches(context.Context, *connect.Request[v1.ListBranchesRequest]) (*connect.Response[v1.ListBranchesResponse], error)
	GetBranch(context.Context, *connect.Request[v1.GetBranchRequest]) (*connect.Response[v1.GetBranchResponse], error)
	SetBranchStatus(context.Context, *connect.Request[v1.SetBranchStatusRequest]) (*connect.Response[v1.SetBranchStatusResponse], error)
	SetBranchDescription(context.Context, *connect.Request[v1.SetBranchDescriptionRequest]) (*connect.Response[v1.SetBranchDescriptionResponse], error)
	ListNodeVersions(context.Context, *connect.Request[v1.ListNodeVersionsRequest]) (*connect.Response[v1.ListNodeVersionsResponse], error)
	// The first versions of the nodes that derive from a node: the successors of the merges and splits that replaced it
	// (ADR 0077). Node.origins answers the other way.
	DerivedNodes(context.Context, *connect.Request[v1.DerivedNodesRequest]) (*connect.Response[v1.DerivedNodesResponse], error)
	PlanMerge(context.Context, *connect.Request[v1.PlanMergeRequest]) (*connect.Response[v1.PlanMergeResponse], error)
	MergeBranch(context.Context, *connect.Request[v1.MergeBranchRequest]) (*connect.Response[v1.MergeBranchResponse], error)
	// What going from a baseline to another changes, node by node (same namespace).
	DiffBaselines(context.Context, *connect.Request[v1.DiffBaselinesRequest]) (*connect.Response[v1.DiffBaselinesResponse], error)
	// Node index (ADR 0026): publishes again the event of every node version and the head of main, to
	// rebuild an index. Requires `admin` on the `platform` resource.
	RepublishIndex(context.Context, *connect.Request[v1.RepublishIndexRequest]) (*connect.Response[v1.RepublishIndexResponse], error)
}

